export function PocchiRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      レゴブロックの突起のこと。<br/>
      レゴ公式情報によると「ポッチ」という呼び方は日本で使われる通称であり、正式には「スタッド」と呼ぶそうですが、ここでは「ポッチ」と記載します。<br/>
      <Image src={pocchi} w='10em' aspectRatio='269 / 205' loading='lazy' />
    </HoverRemark>
  )
}

export function AssociationGameRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop}>
      <AssociationGame />
    </ReferIntoroRemarkFrame>
  )
}

export function AssociationGame() {
  return (
    <>
      まず頭を空っぽにして、でたらめにブロックを組み立てます。(なるべくやったことのないブロックの組み合わせ)<br/>
      それを見て、「柵(さく)の一部に見える」とか「スキーのストックに見える」とか連想するゲーム。<br/>
      結局はレゴブロックなので、本来まったく身の周りのモノと関係ないのですが、"形"や"動き"という点だけに着目して「似てる」と結びつける遊びです。<br/>
      その後、その結びつけたイメージをレゴで作っていきます。<br/>
    </>
  )
}

export function ReverseAssociationGameRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop}>
      でたらめに組み立てたレゴを見て、「柵(さく)の一部に見える」とか「スキーのストックに見える」とか連想して、作っていくゲームを冒頭で紹介しています。<br/>
      それを繰り替えしていると、身の周りにある家具や装置を見て、「レゴならこう作れるかも〜」と逆方向に考えられるようになってくる感じ。<br/>
      そうやって「◯◯がない。じゃぁレゴで用意するか」と工作を手段として使えるようになります。<br/>
    </ReferIntoroRemarkFrame>
  )
}


export function ValuableExperienceRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      小学生の頃、授業中の実験で工作をした際に、『面白いな』と思う仕組みがありました。<br/>
      中学生になり家庭科の授業で「階段の照明を、1階と2階の両方のスイッチからON/OFF制御したい場合、どのように作れば良いか」と問題が出されました。<br/>
      私は、そのものではないですが小学校の頃に『面白いな』と感じた仕組みに似ていたので、少し変えることで仕組みを思い付くことが出来ました。<br/>
      <br/>
      ただ、小学生の同じくラスで実験をしていた友達が、全く思い付かない感じだったことがあります。<br/>
      といっても、その友達と私に能力的な差なんてなく、差があるとしたら実験をした時に『そういった仕組みを以前から面白いと興味を持てていたかどうか』かと、考えています。<br/>
      <br/>
      私も興味がない事はすぐに忘れてしまうので、色々な事に興味を持てることは注意散漫になるかもですが、"発想"という面で大切なことなのかなと感じます。
    </HoverRemark>
  )
}

